// Des: Tests for ru-tier-ladd: M3 gate on the mock vendor
// Flo: mock site + mock vendor > fetch > assert tiers, calls, spend, errors
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const ladd = @import("ru-tier-ladd.zig"); const inde = @import("st-page-inde.zig"); const spen = @import("ru-spen-guar.zig"); const kill = @import("ru-kill-swit.zig"); const vmoc = @import("nt-vend-mock.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, srv2: mock.Mock, vmkz: vmoc.Mock, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, ladz: ladd.Ladd,
pub fn upzz(self: *Rigg, conf: cfgz.Conf, rul2: []const vmoc.Rule) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv2.start(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.vmkz = vmoc.Mock.init(allo); self.vmkz.rul2 = rul2; self.ladz = .{ .gpaz = allo, .iozz = std.testing.io, .conf = conf, .dbzz = &self.dbzz, .dirz = self.dirz, .back = self.vmkz.backend(), .priv = true }; }
pub fn down(self: *Rigg) void { self.vmkz.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv2.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn gozz(self: *Rigg, path: []const u8) !@import("ru-page-fetc.zig").Outc { var buf4: [64]u8 = undefined; return ladd.laddFetc(&self.ladz, self.aren.allocator(), self.srv2.urlzOfzz(&buf4, path)); } };
fn rich() cfgz.Conf { var conf: cfgz.Conf = .{}; conf.vend_free_cred = .{ .deco = 100, .zenr = 100, .brig = 100 }; return conf; }
test "friendly host: T1 only, no vendor call, no spend" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{}); defer rig3.down(); const out2 = try rig3.gozz("/p1"); try std.testing.expectEqualStrings("new", out2.stat); try std.testing.expectEqual(@as(i64, 1), out2.tier); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.calls.items.len); try std.testing.expectEqual(@as(i64, 0), try spen.spenTota(&rig3.dbzz, std.Io.Clock.real.now(std.testing.io).toMilliseconds())); }
test "block page escalates plain -> render, spends free credits, remembers the tier" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{.{ .hasz = "blockp", .minm = .rend }}); defer rig3.down(); const out2 = try rig3.gozz("/blockp"); try std.testing.expectEqualStrings("new", out2.stat); try std.testing.expectEqual(@as(i64, 3), out2.tier); try std.testing.expectEqualStrings("deco", out2.vend); try std.testing.expectEqual(@as(usize, 2), rig3.vmkz.calls.items.len); try std.testing.expectEqual(@as(u32, 2), out2.cred); try std.testing.expectEqual(@as(u64, 0), out2.micr); const nowz = std.Io.Clock.real.now(std.testing.io).toMilliseconds(); try std.testing.expectEqual(@as(i64, 3), try spen.spenUsed(&rig3.dbzz, .deco, @intCast(nowz))); const again = try rig3.gozz("/blockp?x=1"); try std.testing.expectEqualStrings("new", again.stat); try std.testing.expectEqual(@as(usize, 3), rig3.vmkz.calls.items.len); try std.testing.expectEqual(vmoc.Mock.hits(&rig3.vmkz, .deco), 3); try std.testing.expectEqual(@as(@TypeOf(rig3.vmkz.calls.items[2].mode), .rend), rig3.vmkz.calls.items[2].mode); }
test "never retries a block on the same vendor and mode; exhausted ladder = Blocked" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{.{ .hasz = "blockp", .minm = .prem, .body = "x" }}); defer rig3.down(); const out2 = try rig3.gozz("/blockp"); try std.testing.expectEqual(@as(i64, 4), out2.tier); try std.testing.expectEqual(@as(usize, 3), rig3.vmkz.calls.items.len); var seen = std.AutoHashMap(u32, void).init(allo); defer seen.deinit(); for (rig3.vmkz.calls.items) |call| { const key2: u32 = @as(u32, @backingInt(call.vend)) * 10 + @backingInt(call.mode); try std.testing.expect(!seen.contains(key2)); try seen.put(key2, {}); } var rig2: Rigg = undefined; try rig2.upzz(rich(), &.{.{ .hasz = "blockp", .minm = .prem }}); defer rig2.down(); rig2.vmkz.rul2 = &.{.{ .hasz = "blockp", .minm = .prem, .body = "" }}; rig2.ladz.conf.vend_orde = &.{"deco"}; const blkz = rig2.gozz("/blockp"); try std.testing.expectError(error.Blocked, blkz); try std.testing.expectEqual(@as(usize, 3), rig2.vmkz.calls.items.len); }
test "vendor outage falls back to the next vendor in the row" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{}); defer rig3.down(); rig3.vmkz.down[0] = true; const out2 = try rig3.gozz("/e403"); try std.testing.expectEqualStrings("zenr", out2.vend); try std.testing.expectEqual(@as(usize, 2), rig3.vmkz.calls.items.len); }
test "cap stops spend: no free credits and no go means OverCap, zero vendor calls" { var rig3: Rigg = undefined; try rig3.upzz(.{}, &.{}); defer rig3.down(); try std.testing.expectError(error.OverCap, rig3.gozz("/e403")); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.calls.items.len); }
test "paid spend needs go and stays under the cap" { var conf: cfgz.Conf = .{}; conf.capz_usdz_mont = 0.003; conf.vend_orde = &.{"zenr"}; var rig3: Rigg = undefined; try rig3.upzz(conf, &.{}); defer rig3.down(); try std.testing.expectError(error.OverCap, rig3.gozz("/e403")); rig3.ladz.gozz = true; const out2 = try rig3.gozz("/e403"); try std.testing.expectEqual(@as(u64, 1000), out2.micr); const nowz = std.Io.Clock.real.now(std.testing.io).toMilliseconds(); try std.testing.expectEqual(@as(i64, 1000), try spen.spenTota(&rig3.dbzz, @intCast(nowz))); var con2: usize = 0; while (con2 < 5) : (con2 += 1) { var pbuf: [32]u8 = undefined; var bbzz: [64]u8 = undefined; const urlz = try std.fmt.bufPrint(&pbuf, "/e403?n={d}", .{con2}); const full = rig3.srv2.urlzOfzz(&bbzz, urlz); _ = ladd.laddFetc(&rig3.ladz, rig3.aren.allocator(), full) catch {}; } try std.testing.expect(try spen.spenTota(&rig3.dbzz, @intCast(nowz)) <= 3000); }
test "kill switch halts all vendor calls at once" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{}); defer rig3.down(); try kill.killSetz(&rig3.dbzz, true); try std.testing.expectError(error.KillOn, rig3.gozz("/e403")); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.calls.items.len); const free = try rig3.gozz("/p1"); try std.testing.expectEqualStrings("new", free.stat); }
test "own TLS/network failure that is not NeedVendor is returned, not paid around" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{}); defer rig3.down(); try std.testing.expectError(error.NotText, rig3.gozz("/img")); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.calls.items.len); }
test "a friendly page on a host that blocked before still goes out free (no credits)" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{.{ .hasz = "blockp", .minm = .rend }}); defer rig3.down(); _ = try rig3.gozz("/blockp"); const calls = rig3.vmkz.calls.items.len; const out2 = try rig3.gozz("/p1"); try std.testing.expectEqual(@as(i64, 1), out2.tier); try std.testing.expectEqual(calls, rig3.vmkz.calls.items.len); }
test "host whose own GET failed 3 times in a row goes straight to the vendor, no wasted request" { var rig3: Rigg = undefined; try rig3.upzz(rich(), &.{}); defer rig3.down(); var con2: usize = 0; while (con2 < 3) : (con2 += 1) { var pbuf: [32]u8 = undefined; const out2 = try rig3.gozz(try std.fmt.bufPrint(&pbuf, "/e403?n={d}", .{con2})); try std.testing.expect(out2.tier >= 2); } const before = rig3.srv2.hits.load(.monotonic); const four = try rig3.gozz("/e403?n=9"); try std.testing.expect(four.tier >= 2); try std.testing.expectEqual(before, rig3.srv2.hits.load(.monotonic)); }
